static int knapsack(int capacity, List<Item> items) {
    int[] dp = new int[capacity + 1];
    for (Item item : items) {
        for (int w = capacity; w >= item.weight(); w--) {
            dp[w] = Math.max(dp[w], dp[w - item.weight()] + item.value());
        }
    }
    return dp[capacity];
}

