private static void combinationDfs(int[] sorted, int start, int remaining,
                                   List<Integer> current, List<List<Integer>> result) {
    if (remaining == 0) {
        result.add(new ArrayList<>(current));
        return;
    }
    for (int i = start; i < sorted.length; i++) {
        int value = sorted[i];
        if (value > remaining) break;
        current.add(value);
        combinationDfs(sorted, i + 1, remaining - value, current, result);
        current.remove(current.size() - 1);
    }
}

