}
private static boolean visitCycle(Map<String, List<String>> graph, String node,
                                   Map<String, Mark> marks) {
    if (marks.get(node) == Mark.VISITING) return true;
    if (marks.get(node) == Mark.DONE) return false;
    marks.put(node, Mark.VISITING);
    for (String next : graph.getOrDefault(node, List.of())) {
        if (visitCycle(graph, next, marks)) return true;
    }
    marks.put(node, Mark.DONE);
    return false;
}

