static int[] maxSlidingWindow(int[] nums, int k) {
    if (k <= 0 || k > nums.length) throw new IllegalArgumentException("invalid k");
    Deque<Integer> deque = new ArrayDeque<>();
    int[] result = new int[nums.length - k + 1];
    for (int i = 0; i < nums.length; i++) {
        while (!deque.isEmpty() && deque.getFirst() <= i - k) deque.removeFirst();
        while (!deque.isEmpty() && nums[deque.getLast()] <= nums[i]) deque.removeLast();
        deque.addLast(i);
        if (i >= k - 1) result[i - k + 1] = nums[deque.getFirst()];
    }
    return result;
}

