static <T> List<T> topologicalSort(Graph<T> graph) {
    Map<T, Integer> inDegree = new LinkedHashMap<>();
    for (T vertex : graph.vertices()) inDegree.put(vertex, 0);
    for (T vertex : graph.vertices()) {
        for (T next : graph.neighbors(vertex)) inDegree.merge(next, 1, Integer::sum);
    }
    Deque<T> queue = new ArrayDeque<>();
    inDegree.forEach((vertex, degree) -> { if (degree == 0) queue.add(vertex); });
    List<T> result = new ArrayList<>();
    while (!queue.isEmpty()) {
        T vertex = queue.removeFirst();
        result.add(vertex);
        for (T next : graph.neighbors(vertex)) {
            int degree = inDegree.merge(next, -1, Integer::sum);
            if (degree == 0) queue.add(next);
        }
    }
    return result.size() == graph.vertices().size() ? result : null;
}

