static <T> Map<T, Integer> dijkstra(Map<T, List<Edge<T>>> graph, T start) {
    Map<T, Integer> dist = new HashMap<>();
    dist.put(start, 0);
    PriorityQueue<Edge<T>> queue = new PriorityQueue<>(Comparator.comparingInt(Edge::weight));
    queue.add(new Edge<>(start, 0));
    while (!queue.isEmpty()) {
        Edge<T> current = queue.remove();
        if (current.weight() != dist.get(current.node())) continue;
        for (Edge<T> edge : graph.getOrDefault(current.node(), List.of())) {
            if (edge.weight() < 0) throw new IllegalArgumentException("negative edge");
            int candidate = Math.addExact(current.weight(), edge.weight());
            if (candidate < dist.getOrDefault(edge.node(), Integer.MAX_VALUE)) {
                dist.put(edge.node(), candidate);
                queue.add(new Edge<>(edge.node(), candidate));
            }
        }
    }
    return dist;
}

