static byte[] concat(byte[] left, byte[] right) {
    byte[] combined = Arrays.copyOf(left, left.length + right.length);
    System.arraycopy(right, 0, combined, left.length, right.length);
    return combined;
}
static byte[] merkleRoot(List<byte[]> leaves) {
    if (leaves.isEmpty()) throw new IllegalArgumentException("empty leaves");
    List<byte[]> level = new ArrayList<>();
    for (byte[] leaf : leaves) level.add(hash(leaf));
    while (level.size() > 1) {
        List<byte[]> next = new ArrayList<>();
        for (int i = 0; i < level.size(); i += 2) {
            byte[] left = level.get(i);
            byte[] right = i + 1 < level.size() ? level.get(i + 1) : left;
            next.add(hash(concat(left, right)));
        }
        level = next;
    }
    return level.get(0);
}
record ProofStep(byte[] sibling, boolean leftSibling) {}
static boolean verifyMerkleProof(byte[] leaf, List<ProofStep> proof, byte[] expectedRoot) {
    byte[] current = hash(leaf);
    for (ProofStep step : proof) {
        current = hash(step.leftSibling()
            ? concat(step.sibling(), current) : concat(current, step.sibling()));
    }
    return Arrays.equals(current, expectedRoot);
}

